result=js(r'''(async()=>{
const T=await import('three'),{createHeroRealm,HERO_BOUNDS}=await import('./js/world/hero-realm.js'),{townhouseMaterials}=await import('./js/world/building-slice-materials.js');
const check=(v,m)=>{if(!v)throw Error(m)},g=createHeroRealm(),m=townhouseMaterials(),maps=new Set();let triangles=0;
check(g.children.length<=4,'renderable budget');check(JSON.stringify(HERO_BOUNDS)===JSON.stringify({x0:-293,x1:-273,z0:-24,z1:24}),'exact zone');
for(const mesh of g.children){check(mesh.material===m.architecture||mesh.material===m.glass,'shared materials');Object.values(mesh.material).forEach(v=>{if(v?.isTexture)maps.add(v)});const a=mesh.geometry.attributes;triangles+=a.position.count/3;check(mesh.geometry.boundingBox&&mesh.geometry.boundingSphere&&mesh.frustumCulled,'bounds');for(const name of ['position','normal','uv','aSurface','color'])check(a[name]?.count===a.position.count,'attributes');for(let i=0;i<a.position.count;i++){const x=a.position.getX(i)+g.position.x,z=a.position.getZ(i)+g.position.z;check(x>=-293.001&&x<=-272.999&&z>=-24.001&&z<=24.001,'local scope');}}
const {stops}=await import('./js/content.js'),{buildCity}=await import('./js/world/city.js'),{routePoints,routeCurve}=await import('./js/world/layout.js');
const pts=routePoints(stops.length),curve=routeCurve(T,pts),collect=replace=>{const boxes=[],trees=[],plots=[],zones=[];buildCity((...b)=>boxes.push(b),stops,pts,curve,(...t)=>trees.push(t),undefined,p=>plots.push(p),replace?p=>zones.push(p):undefined);return {boxes,trees,plots,zones}};
const before=collect(false),after=collect(true);check(after.zones.length===1,'single scene integration zone');check(JSON.stringify(before.plots)===JSON.stringify(after.plots),'all building descriptors unchanged');check(JSON.stringify(before.trees)===JSON.stringify(after.trees),'all tree placements unchanged');const outside=b=>b[0]<-293.5||b[0]>-272.5||b[2]<-24.5||b[2]>24.5;check(JSON.stringify(before.boxes.filter(outside))===JSON.stringify(after.boxes.filter(outside)),'all other city geometry unchanged');
check(triangles<=12000&&maps.size===4,'geometry/resource budget');check(g.userData.newLights===0,'no dynamic lights');for(const o of g.userData.obstacles){const r=o.rect;check(!(r.x0<1.7&&r.x1>-1.7)&&!(r.z0<1.5&&r.z1>-1.5)||o.kind==='fountain','central paths clear');}
const fp=g=>JSON.stringify(g.children.map(o=>Object.fromEntries(Object.entries(o.geometry.attributes).map(([k,a])=>[k,Array.from(a.array)]))));check(fp(g)===fp(createHeroRealm()),'deterministic');let disposed=0;g.children.forEach(o=>o.geometry.addEventListener('dispose',()=>disposed++));g.userData.dispose();g.userData.dispose();check(disposed===g.children.length,'owned geometry disposed once');return {pass:true,renderables:g.children.length,triangles,materials:2,maps:maps.size,newLights:0};})()''')
print(result)
assert isinstance(result,dict) and result.get('pass'),result
